// Lets you choose which game to play when challenging a friend, instead
// of it always forcing "Grille". Tapping the ⚔️ button on a friend now
// opens a small picker (Devine le joueur / Grille / Devine le club / Liste
// / XI Type); whichever you pick pre-targets that friend in the matching
// duel screen so you don't have to find them again in a friends list you
// were just looking at. Invite notifications + accept/decline already
// existed for every one of these modes (grid_duels for Grille, group_games
// for the others) — this only fixes how you get there.
// Includes this file's own copy of the earlier XI Type autocomplete fix
// (QuizListScreen.tsx / XIDuelScreen.tsx) — applying this patch alone is
// enough even if that one wasn't applied yet; no conflict if it already was.
// JS-only change — an EAS Update (OTA) is enough, no native rebuild needed.
// Run from strikr-app/: node patch-friend-challenge-game-picker.js
const fs = require('fs');
const path = require('path');

function write(rel, content) {
  const full = path.join(process.cwd(), rel);
  fs.writeFileSync(full, content);
  console.log('WROTE', rel);
}

